import java.util.*;

class Solution {
    public int[][] refoldGrid(int[][] grid, int newRows, int newCols) {
        int rows = grid.length, cols = grid[0].length;
        if (rows * cols != newRows * newCols) {
            return grid;                         // sizes don't match: unchanged
        }
        int[][] result = new int[newRows][newCols];
        for (int k = 0; k < rows * cols; k++) {
            // k-th cell in reading order: old position -> new position
            result[k / newCols][k % newCols] = grid[k / cols][k % cols];
        }
        return result;
    }
}

