class Solution:
    def refoldGrid(self, grid: List[List[int]], newRows: int, newCols: int) -> List[List[int]]:
        r, c = len(grid), len(grid[0])
        if r * c != newRows * newCols: return grid
        flat = [v for row in grid for v in row]
        return [flat[i * newCols:(i + 1) * newCols] for i in range(newRows)]

