function refoldGrid(grid, newRows, newCols) {
  const r = grid.length, c = grid[0].length;
  if (r * c !== newRows * newCols) return grid;
  const out = Array.from({ length: newRows }, () => new Array(newCols));
  for (let k = 0; k < r * c; k++) out[Math.floor(k / newCols)][k % newCols] = grid[Math.floor(k / c)][k % c];
  return out;
}
